    const [reextractId,setReextractId]=useState<string|null>(null);

    const [bundle, setBundle] = useState<{task: ProductionTask; attemptId: string; baseline: ProductionCreationState; candidate: ReturnType<typeof productionArtifactBundleDraft>; accepted: boolean; productionToken: string} | null>(null);
    const [adopted, setAdopted] = useState<string[]>([]);
    const [segmentBody,setSegmentBody]=useState<string|null>(null);
    const [segmentEditorOpen,setSegmentEditorOpen]=useState(false);

    const [historyQuery, setHistoryQuery] = useState(''), [historyRestore, setHistoryRestore] = useState<string | null>(null);
    const dirty = JSON.stringify(draft) !== JSON.stringify(state?.creation ?? null) || !!feedback.trim() || segmentBody!==null&&segmentBody!==state?.content.body; useManagedDraftGuard(dirty);
    const blocked = busy || pending;
    function apply(next: ProductionCreationState) {setState(next); setDraft(next.creation);setSegmentBody(null);}
