        const result=await invoke('startProductionTask',{kind:'transcription',businessSkill:'jc-benchmark-intake',title:`${content.title.slice(0,430)} · ${label}`,prompt:`${label}：${reference.title}。只处理固定参考，保留来源与已保存证据；原始稿与校正版分开。`,contentId:content.id,mode:'simple',comments:false,transcript:{intent,referenceId,expectedReferenceHash}});
        setReextractId(null);await reload();setNotice(result.message??(result.opened?'已打开助手，请在同一个任务中处理本条参考；提交并验收后回这里预览再采用。':'任务已保留，请从原任务继续。'));
